    -- ---- assertions: everything must balance exactly before we commit ----
    select count(*) into v_count
      from public.transactions where account_id = v_aid and reference like 'NTB-MK%';
    if v_count < 100 then
      raise exception '020: only % mock rows inserted (expected 100+) - rolling back', v_count;
    end if;

    select coalesce(sum(case when direction = 'credit' then amount else -amount end), 0)
      into v_net
      from public.transactions where account_id = v_aid;
    if v_net <> v_final then
      raise exception '020: transaction history nets to %, expected % - rolling back', v_net, v_final;
    end if;

    select coalesce(min(rb), 0) into v_worst from (
      select sum(case when direction = 'credit' then amount else -amount end)
             over (order by created_at, id
                   rows between unbounded preceding and current row) as rb
        from public.transactions where account_id = v_aid
    ) running;
    if v_worst < 0 then
      raise exception '020: running balance goes negative (low point %) - rolling back', v_worst;
    end if;

    update public.account_balances
       set available_balance = v_final,
           ledger_balance    = v_final,
           updated_at        = now()
     where account_id = v_aid;
    if not found then
      raise exception '020: account_balances row missing - rolling back';
    end if;

    raise notice '020: inserted % mock transactions, balance now %', v_count, v_final;
  end if;
end $$;
